mapper.select:
select  from game_runtime_session s
 where s.activity_id=#{activityId} and s.topic_id=#{topicId} and s.node_id=#{nodeId}
   and s.owner_type=#{ownerType} and s.owner_id=#{ownerId} and s.play_instance_id=#{playInstanceId}
 limit 1

select  from game_runtime_session s
where s.activity_id=#{activityId} and s.topic_id=#{topicId}
  and s.owner_type=1 and s.owner_id=#{memberId}
order by s.id

mapper.update:
update game_runtime_session set state_json=#{stateJson},version=version+1,update_time=#{updateTime}
where id=#{id} and version=#{version} and owner_type=#{ownerType} and owner_id=#{ownerId}
  and status=#{status} and status in (1,2,3)

mapper.select:
select s.owner_type as ownerType, s.owner_id as ownerId, case when s.owner_type=1 then coalesce(u.nickname, '玩家') else coalesce(t.title, '队伍') end as displayName, s.score, s.completed_units as completedUnits, timestampdiff(second, s.started_at, coalesce(s.completed_at, s.update_time)) as elapsedSeconds, s.completed_at as completedAt from game_runtime_session s left join ums_member u on s.owner_type=1 and u.id=s.owner_id left join play_team t on s.owner_type=2 and t.id=s.owner_id where s.node_id=#{nodeId} and s.status=1
and s.activity_id=#{activityId} and s.topic_id=#{topicId}
order by elapsedSeconds asc, s.completed_at asc, s.id asc
order by s.completed_units desc, s.update_time asc, s.id asc
order by s.score desc, elapsedSeconds asc, s.id asc
limit #{limit}
